do $store$ declare n bigint; begin
	execute 'select count(*)::int as n from "holding" where ("accrued_interest" not in (''NaN''::numeric, ''Infinity''::numeric, ''-Infinity''::numeric) and round("accrued_interest", 2) = "accrued_interest") is false' into n;
	if n > 0 then raise exception 'holding__ck__fce56b0e refuses % existing row(s)', n; end if;
end $store$;
